import pandas as pd, numpy as np
r=np.load('/tmp/res.npy'); rd,ry,rp=r[:,0],r[:,1],r[:,2]
vrd,vry,vrp=rd.var(),ry.var(),rp.var()
print('var rd,ry,rp:',vrd,vry,vrp, 'diff vry-vrp:',vry-vrp)
s1=np.sum(rd*ry)/np.sum(rd*rd); s2=np.sum(rd*rp)/np.sum(rd*rd); s3=np.sum(rp*ry)/np.sum(rp*rp)
print('slopes:',s1,s2,s3)
from scipy.optimize import brentq
def f(k):
    th=s1-k*s2
    G=s3*vrp/k
    return G*(k-1/k) + (th**2+2*th*k*s2)*vrd - (vry-vrp)
for k in [0.6,0.8,1.0,1.2,1.5,2.0,3.0]:
    print(k, f(k), 'theta=', s1-k*s2)
try:
    ksol=brentq(f,0.3,10); print('k*=',ksol,'theta=',s1-ksol*s2)
except Exception as e: print(e)
